              <BookOpen className="h-5 w-5 text-[#2563EB]" />
            </div>
            <div>
              <h3 className="text-base font-semibold text-slate-900">
                Growth Reflection
              </h3>
              <p className="text-xs text-slate-500">
                Reflect on: {habit.title}
              </p>
            </div>
          </div>
          <button
            onClick={onClose}
            className="text-slate-400 transition-colors hover:text-slate-900"
          >
            <X className="h-5 w-5" />
          </button>
        </div>

        <form onSubmit={handleSubmit} className="space-y-4">
          {questions.map((q) => (
            <div key={q.key}>
              <label className="mb-1 block text-xs font-medium text-slate-500">
                {q.question}
              </label>
              <input
                type="text"
                value={metrics[q.key] || ""}
                onChange={(e) =>
                  setMetrics({ ...metrics, [q.key]: e.target.value })
                }
                placeholder={q.placeholder}
                className="w-full rounded-lg border border-slate-200 bg-slate-50 px-3 py-2 text-sm text-slate-900 placeholder:text-slate-400 focus:border-[#2563EB] focus:outline-none"
              />
            </div>
          ))}

          <div>
            <label className="mb-1 block text-xs font-medium text-slate-500">
              Your reflection * (required)
            </label>
            <textarea
              required
              value={reflection}
              onChange={(e) => setReflection(e.target.value)}
              rows={4}
              placeholder="How did this go? What did you learn? What will you do differently next time?"
              className="w-full rounded-lg border border-slate-200 bg-slate-50 px-3 py-2 text-sm text-slate-900 placeholder:text-slate-400 focus:border-[#2563EB] focus:outline-none"
            />
          </div>

          <div className="rounded-lg bg-slate-50 p-3 text-center">
            <p className="text-xs text-slate-500">
              Earn <span className="font-semibold text-[#10B981]">{habit.xpReward} XP</span> after saving your reflection
            </p>
          </div>

          <div className="flex justify-end gap-3 pt-2">
            <button
              type="button"
              onClick={onClose}
              className="rounded-lg border border-slate-200 px-4 py-2 text-sm text-slate-500 transition-colors hover:bg-slate-100"
            >
              Skip
            </button>
            <button
              type="submit"
              disabled={loading || !reflection.trim()}
              className="flex items-center gap-2 rounded-lg bg-[#2563EB] px-4 py-2 text-sm font-medium text-white transition-colors hover:bg-[#1D4ED8] disabled:opacity-50"
            >
              {loading && <Loader2 className="h-4 w-4 animate-spin" />}
              Save Reflection
            </button>
          </div>
        </form>
        </div>
      </div>
    </div>
  );
}

"use client";

import { useState, useEffect } from "react";
import { cn } from "@/lib/cn";
import { Clock } from "lucide-react";

interface PremiumTimePickerProps {
  value: number;
  onChange: (v: number) => void;
  max?: number;
  label?: string;
  className?: string;
}

export default function PremiumTimePicker({
  value,
  onChange,
  max = 180,
  label,
  className,
}: PremiumTimePickerProps) {
  const [minutes, setMinutes] = useState(Math.floor(value / 60));
  const [seconds, setSeconds] = useState(value % 60);

  useEffect(() => {
    const total = minutes * 60 + seconds;
    onChange(Math.min(total, max * 60));
  }, [minutes, seconds, max, onChange]);

  const displayMinutes = Math.floor(value / 60);
  const displaySeconds = value % 60;

  return (
    <div className={cn("space-y-2", className)}>
      {label && (
        <div className="flex items-center gap-2">
          <Clock className="h-4 w-4 text-[#2563EB]" />
          <span className="text-sm font-medium text-slate-700">{label}</span>
        </div>
      )}
      <div className="flex items-center gap-2">
        <div className="flex items-center gap-1">
          <input
            type="number"
            min={0}
            max={Math.floor(max / 60)}
            value={displayMinutes}
            onChange={(e) => {
              const m = parseInt(e.target.value) || 0;
              onChange(Math.min(m * 60 + displaySeconds, max * 60));
            }}
            className="w-16 rounded-xl border border-slate-200 bg-slate-50 px-3 py-2.5 text-center text-lg font-bold text-slate-900 focus:border-[#2563EB] focus:outline-none tabular-nums"
            aria-label="Minutes"
          />
          <span className="text-lg font-bold text-slate-400">:</span>
          <input
            type="number"
            min={0}
            max={59}
            value={String(displaySeconds).padStart(2, "0")}
            onChange={(e) => {
              const s = parseInt(e.target.value) || 0;
              onChange(Math.min(displayMinutes * 60 + Math.min(s, 59), max * 60));
            }}
            className="w-16 rounded-xl border border-slate-200 bg-slate-50 px-3 py-2.5 text-center text-lg font-bold text-slate-900 focus:border-[#2563EB] focus:outline-none tabular-nums"
            aria-label="Seconds"
          />
        </div>
        <span className="text-xs text-slate-400">min:sec</span>
      </div>
    </div>
  );
}
